impl Solution {
    pub fn min_operations(nums: Vec<i32>) -> i32 {
        let n = nums.len();
        let mut adjusted_nums = nums.clone();
        for i in (1..n).rev() {
            if adjusted_nums[i] <= adjusted_nums[i - 1] {
                adjusted_nums[i] = adjusted_nums[i - 1] + 1;
            }
        }

        let mut operations = 0;
        for i in 1..n {
            operations += adjusted_nums[i] - nums[i];
        }

        operations
    }
}

